import { handleOptions, jsonResponse } from "../_shared/cors.ts";
import { getUserFromAuthHeader, supabaseAdmin } from "../_shared/supabaseAdmin.ts";
import { withinLimit } from "../_shared/rateLimit.ts";
import { consumeProductPurchase, getProductPurchase, getProductPurchaseV2, GoogleApiError, sha256Hex } from "../_shared/googlePlay.ts";
import { validatePlayPurchaseV2 } from "../_shared/playPurchaseValidation.ts";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
Deno.serve(async (req: Request) => {
  const preflight = handleOptions(req); if (preflight) return preflight;
  if (req.method !== "POST") return jsonResponse({ error: "Method not allowed." }, 405);
  const user = await getUserFromAuthHeader(req);
  if (!user) return jsonResponse({ error: "Please log in before purchasing." }, 401);
  const body = await req.json().catch(() => ({})) as { purchaseToken?: unknown; productId?: unknown; internalOrderId?: unknown };
  const token = typeof body.purchaseToken === "string" ? body.purchaseToken : "";
  const productId = typeof body.productId === "string" ? body.productId : "";
  const orderId = typeof body.internalOrderId === "string" ? body.internalOrderId : "";
  if (!UUID.test(orderId) || !productId || productId.length > 100 || token.length < 10 || token.length > 4096)
    return jsonResponse({ error: "Invalid purchase details." }, 400);
  if (!(await withinLimit(`verify-play:${user.id}`, 60, 600))) return jsonResponse({ error: "Too many attempts." }, 429);
  const { data: order, error: orderError } = await supabaseAdmin.from("orders")
    .select("id,user_id,product_id,provider,play_sku,play_purchase_option_id,amount,status,purchase_token,external_transaction_token,external_choice_bound_order_id")
    .eq("id", orderId).maybeSingle();
  if (orderError || !order || order.user_id !== user.id || order.product_id !== productId || order.provider !== "play"
      || !order.play_sku || order.external_transaction_token || order.external_choice_bound_order_id
      || (order.purchase_token && order.purchase_token !== token))
    return jsonResponse({ error: "Purchase order mismatch." }, 403);
  try {
    let paidMillis: number;
    let consumed: boolean;
    if (order.play_purchase_option_id) {
      const purchase = await getProductPurchaseV2(token);
      const checked = validatePlayPurchaseV2(purchase, {
        sku: order.play_sku, optionId: order.play_purchase_option_id,
        accountHash: await sha256Hex(user.id), orderHash: await sha256Hex(orderId), now: Date.now(),
      });
      if (checked.status === "pending")
        return jsonResponse({ success: false, pending: true, internalOrderId: orderId });
      if (checked.status === "invalid")
        return jsonResponse({ error: "Play purchase did not match this order." }, 403);
      paidMillis = checked.paidMillis;
      consumed = checked.consumed;
    } else {
      // Existing orders predate the BUY-option snapshot. Keep their v1 recovery path.
      const purchase = await getProductPurchase(order.play_sku, token);
      if (purchase.purchaseState === 2) return jsonResponse({ success: false, pending: true, internalOrderId: orderId });
      if (purchase.purchaseState !== 0 || purchase.refundableQuantity === 0
          || (purchase.productId && purchase.productId !== order.play_sku)
          || (purchase.purchaseToken && purchase.purchaseToken !== token)
          || purchase.regionCode !== "IN" || (purchase.quantity ?? 1) !== 1
          || purchase.obfuscatedExternalAccountId !== await sha256Hex(user.id)
          || purchase.obfuscatedExternalProfileId !== await sha256Hex(orderId))
        return jsonResponse({ error: "Play purchase did not match this order." }, 403);
      paidMillis = Number(purchase.purchaseTimeMillis);
      consumed = purchase.consumptionState === 1;
    }
    if (!Number.isSafeInteger(paidMillis) || paidMillis <= 0 || paidMillis > Date.now() + 300_000)
      return jsonResponse({ error: "Play purchase time invalid." }, 403);
    if (consumed && order.status !== "paid")
      return jsonResponse({ error: "Play purchase was already consumed." }, 409);
    const { data: settlement, error: settleError } = await supabaseAdmin.rpc("settle_play_purchase", {
      p_user_id: user.id, p_order_id: orderId, p_product_id: productId,
      p_play_sku: order.play_sku, p_purchase_token: token, p_paid_at: new Date(paidMillis).toISOString(),
    });
    if (settleError || !settlement?.ok) {
      console.error("verify-play-purchase settlement failed", settleError?.code);
      return jsonResponse({ error: "Purchase confirmation pending. Please retry." }, 503);
    }
    if (consumed) {
      await supabaseAdmin.from("orders").update({ play_consumption_status: "consumed" }).eq("id", orderId).eq("purchase_token", token);
    } else {
      try {
        await consumeProductPurchase(order.play_sku, token);
        await supabaseAdmin.from("orders").update({ play_consumption_status: "consumed" }).eq("id", orderId).eq("purchase_token", token);
      } catch (error) {
        console.error("verify-play-purchase consumption pending", error instanceof GoogleApiError ? error.status : String(error));
        await supabaseAdmin.from("orders").update({ play_consumption_status: "failed" }).eq("id", orderId).eq("purchase_token", token);
      }
    }
    const { data: product } = await supabaseAdmin.from("products").select("title").eq("id", productId).maybeSingle();
    if (settlement.duplicate) return jsonResponse({ error: "This product was already owned; contact support for a refund." }, 409);
    return jsonResponse({ success: true, internalOrderId: orderId, amount: Number(settlement.amount),
      productTitle: product?.title ?? "Your content" });
  } catch (error) {
    console.error("verify-play-purchase API unavailable", error instanceof GoogleApiError ? error.status : String(error));
    return jsonResponse({ error: "Play verification unavailable. Please retry." }, 503);
  }
});

// supabase/functions/_shared/cors.ts

export const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

export function handleOptions(req: Request): Response | null {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  return null;
}

// JSON response helper. "pay" and "verify-payment" used to return HTML
// pages meant for an external browser - Supabase doesn't serve real
// text/html on the default *.supabase.co domain (scripts get sandboxed
// and blocked), which is why the checkout button did nothing. They now
// return JSON, and the checkout UI runs inside the app's own WebView.
export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

import { createClient } from "npm:@supabase/supabase-js@2";

// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are injected automatically
// into every Edge Function's environment - no need to set them manually
// via `supabase secrets set`. The service role key bypasses RLS, which
// this backend needs: it has to read/write orders, purchases, and
// payment_sessions across users, not just the calling user's own rows.
const supabaseUrl = Deno.env.get("SUPABASE_URL");
const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

if (!supabaseUrl || !serviceRoleKey) {
  throw new Error("Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY Edge Function environment variable.");
}

export const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey, {
  auth: { persistSession: false, autoRefreshToken: false },
});

// Verifies the bearer token from an incoming request's Authorization
// header and returns the authenticated user - the only thing that should
// ever identify who's paying. Never trust a uid passed as a plain body/
// query param, since that would let anyone buy a product "as" someone
// else.
export async function getUserFromAuthHeader(
  req: Request
): Promise<{ id: string; email?: string } | null> {
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "");
  if (!token) return null;

  const { data, error } = await supabaseAdmin.auth.getUser(token);
  if (error || !data.user) return null;

  return { id: data.user.id, email: data.user.email ?? undefined };
}

// The session's authentication assurance level ("aal1" = password only, "aal2" = MFA done).
// Only call this AFTER getUserFromAuthHeader() accepted the same token: it decodes the payload
// without re-verifying the signature.
export function aalFromAuthHeader(req: Request): string {
  const token = (req.headers.get("Authorization") ?? "").replace(/^Bearer\s+/i, "");
  try {
    const b64 = token.split(".")[1].replace(/-/g, "+").replace(/_/g, "/");
    const claims = JSON.parse(atob(b64.padEnd(Math.ceil(b64.length / 4) * 4, "=")));
    return typeof claims.aal === "string" ? claims.aal : "";
  } catch {
    return "";
  }
}

import { supabaseAdmin } from "./supabaseAdmin.ts";

export async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
}

export function clientIp(req: Request): string {
  const forwarded = req.headers.get("cf-connecting-ip")
    ?? req.headers.get("x-real-ip")
    ?? req.headers.get("x-forwarded-for")?.split(",")[0]
    ?? "unknown";
  return forwarded.trim() || "unknown";
}

// true = within limit. By default fails OPEN on a database error (availability of the
// endpoint; the auth provider's own limits still apply behind it). Pass failClosed for
// brute-force-sensitive endpoints (password login) where "limiter down" must not mean
// "no limit".
export async function withinLimit(
  key: string,
  limit: number,
  windowSeconds: number,
  failClosed = false,
): Promise<boolean> {
  const { data, error } = await supabaseAdmin.rpc("rate_limit_hit", {
    p_key: await sha256Hex(key),
    p_limit: limit,
    p_window_seconds: windowSeconds,
  });
  if (error) {
    console.error("rateLimit: rpc failed", error.code);
    return !failClosed;
  }
  return data === true;
}

// Google Play Developer API. References:
// https://developers.google.com/android-publisher/api-ref/rest/v3/purchases.products
// https://developers.google.com/android-publisher/api-ref/rest/v3/externaltransactions
const SCOPE = "https://www.googleapis.com/auth/androidpublisher";
const API = "https://androidpublisher.googleapis.com/androidpublisher/v3";
const encoder = new TextEncoder();
let cached: { token: string; until: number } | null = null;

export type ProductPurchase = {
  purchaseState?: number;
  consumptionState?: number;
  acknowledgementState?: number;
  purchaseTimeMillis?: string;
  productId?: string;
  purchaseToken?: string;
  quantity?: number;
  regionCode?: string;
  refundableQuantity?: number;
  obfuscatedExternalAccountId?: string;
  obfuscatedExternalProfileId?: string;
};

function env(name: string): string {
  const value = Deno.env.get(name);
  if (!value) throw new Error(`Missing ${name}`);
  return value;
}

export function packageName(): string {
  const value = env("GOOGLE_PLAY_PACKAGE_NAME");
  if (value !== "in.medveda.app") throw new Error("GOOGLE_PLAY_PACKAGE_NAME must match in.medveda.app");
  return value;
}

function b64url(bytes: Uint8Array): string {
  let value = "";
  for (const byte of bytes) value += String.fromCharCode(byte);
  return btoa(value).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

async function serviceAccountToken(): Promise<string> {
  if (cached && Date.now() < cached.until - 60_000) return cached.token;
  let serviceAccount: { client_email?: string; private_key?: string };
  try {
    serviceAccount = JSON.parse(env("GOOGLE_PLAY_SERVICE_ACCOUNT_JSON"));
  } catch { throw new Error("Invalid GOOGLE_PLAY_SERVICE_ACCOUNT_JSON"); }
  if (!serviceAccount.client_email || !serviceAccount.private_key) throw new Error("Incomplete Google service account");
  const pem = serviceAccount.private_key.replace(/-----BEGIN PRIVATE KEY-----|-----END PRIVATE KEY-----|\s/g, "");
  const binary = atob(pem);
  const keyBytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
  const key = await crypto.subtle.importKey("pkcs8", keyBytes, { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["sign"]);
  const now = Math.floor(Date.now() / 1000);
  const header = b64url(encoder.encode(JSON.stringify({ alg: "RS256", typ: "JWT" })));
  const payload = b64url(encoder.encode(JSON.stringify({ iss: serviceAccount.client_email, scope: SCOPE,
    aud: "https://oauth2.googleapis.com/token", iat: now, exp: now + 3600 })));
  const input = `${header}.${payload}`;
  const signature = b64url(new Uint8Array(await crypto.subtle.sign("RSASSA-PKCS1-v1_5", key, encoder.encode(input))));
  const response = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST", signal: AbortSignal.timeout(15_000), headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer", assertion: `${input}.${signature}` }),
  });
  if (!response.ok) throw new Error(`Google OAuth returned ${response.status}`);
  const value = await response.json().catch(() => null) as { access_token?: string; expires_in?: number } | null;
  if (!value?.access_token || !Number.isFinite(value.expires_in)) throw new Error("Google OAuth response invalid");
  cached = { token: value.access_token, until: Date.now() + Math.min(value.expires_in as number, 3600) * 1000 };
  return cached.token;
}

export class GoogleApiError extends Error {
  constructor(public readonly status: number) { super(`Google Play API returned ${status}`); }
}

export async function googleRequest<T>(method: "GET" | "POST" | "PATCH", path: string, body?: unknown): Promise<T> {
  const response = await fetch(`${API}${path}`, {
    method, signal: AbortSignal.timeout(15_000),
    headers: { Authorization: `Bearer ${await serviceAccountToken()}`,
      ...(body === undefined ? {} : { "Content-Type": "application/json" }) },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  });
  if (!response.ok) throw new GoogleApiError(response.status);
  const text = await response.text();
  if (!text) return {} as T;
  try { return JSON.parse(text) as T; } catch { throw new Error("Google Play API response invalid"); }
}

function productPath(sku: string, token: string): string {
  return `/applications/${encodeURIComponent(packageName())}/purchases/products/${encodeURIComponent(sku)}/tokens/${encodeURIComponent(token)}`;
}

export function getProductPurchase(sku: string, token: string): Promise<ProductPurchase> {
  return googleRequest<ProductPurchase>("GET", productPath(sku, token));
}

export type ProductPurchaseV2 = {
  purchaseStateContext?: { purchaseState?: string };
  productLineItem?: { productId?: string; productOfferDetails?: {
    purchaseOptionId?: string; offerId?: string; quantity?: number;
    refundableQuantity?: number; consumptionState?: string;
  } }[];
  regionCode?: string;
  purchaseCompletionTime?: string;
  obfuscatedExternalAccountId?: string;
  obfuscatedExternalProfileId?: string;
};

export function getProductPurchaseV2(token: string): Promise<ProductPurchaseV2> {
  return googleRequest<ProductPurchaseV2>("GET",
    `/applications/${encodeURIComponent(packageName())}/purchases/productsv2/tokens/${encodeURIComponent(token)}`);
}

export function consumeProductPurchase(sku: string, token: string): Promise<Record<string, never>> {
  return googleRequest<Record<string, never>>("POST", `${productPath(sku, token)}:consume`);
}

export type VoidedPurchase = { purchaseToken?: string; voidedTimeMillis?: string };
export type VoidedPurchasesPage = {
  voidedPurchases?: VoidedPurchase[];
  tokenPagination?: { nextPageToken?: string };
};

export function getVoidedPurchasesPage(startTime: number, pageToken?: string, endTime?: number,
  maxResults = 200): Promise<VoidedPurchasesPage> {
  if (!Number.isSafeInteger(maxResults) || maxResults < 1 || maxResults > 200) throw new Error("Invalid void page size");
  const query = new URLSearchParams({
    startTime: String(startTime), type: "0", "pageSelection.maxResults": String(maxResults),
  });
  if (endTime) query.set("endTime", String(endTime));
  if (pageToken) query.set("pageSelection.token", pageToken);
  return googleRequest<VoidedPurchasesPage>("GET",
    `/applications/${encodeURIComponent(packageName())}/purchases/voidedpurchases?${query}`);
}

export async function sha256Hex(value: string): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", encoder.encode(value)));
  return Array.from(digest, (byte) => byte.toString(16).padStart(2, "0")).join("");
}

export type ExternalTransaction = {
  externalTransactionId?: string;
  packageName?: string;
  transactionState?: string;
  oneTimeTransaction?: { externalTransactionToken?: string };
  originalPreTaxAmount?: { currency?: string; priceMicros?: string };
  originalTaxAmount?: { currency?: string; priceMicros?: string };
  currentPreTaxAmount?: { currency?: string; priceMicros?: string };
  currentTaxAmount?: { currency?: string; priceMicros?: string };
  userTaxAddress?: { regionCode?: string; administrativeArea?: string };
  transactionTime?: string;
};

function externalPath(id?: string): string {
  const base = `/applications/${encodeURIComponent(packageName())}/externalTransactions`;
  return id ? `${base}/${encodeURIComponent(id)}` : base;
}

export function createExternalTransaction(id: string, data: Record<string, unknown>): Promise<ExternalTransaction> {
  return googleRequest<ExternalTransaction>("POST", `${externalPath()}?externalTransactionId=${encodeURIComponent(id)}`, data);
}

export function getExternalTransaction(id: string): Promise<ExternalTransaction> {
  return googleRequest<ExternalTransaction>("GET", externalPath(id));
}

export function refundExternalTransaction(id: string, refundTime: string): Promise<ExternalTransaction> {
  return googleRequest<ExternalTransaction>("POST", `${externalPath(id)}:refund`, { refundTime, fullRefund: {} });
}

export function refundExternalTransactionPartially(id: string, refundId: string,
  preTaxMicros: string, refundTime: string): Promise<ExternalTransaction> {
  return googleRequest<ExternalTransaction>("POST", `${externalPath(id)}:refund`, {
    refundTime,
    partialRefund: { refundId, refundPreTaxAmount: { currency: "INR", priceMicros: preTaxMicros } },
  });
}

import type { ProductPurchaseV2 } from "./googlePlay.ts";

export type PurchaseCheck =
  | { status: "pending" }
  | { status: "invalid" }
  | { status: "valid"; paidMillis: number; consumed: boolean };

export function validatePlayPurchaseV2(purchase: ProductPurchaseV2, expected: {
  sku: string; optionId: string; accountHash: string; orderHash: string; now: number;
}): PurchaseCheck {
  if (purchase.purchaseStateContext?.purchaseState === "PENDING") return { status: "pending" };
  const line = purchase.productLineItem?.[0];
  const details = line?.productOfferDetails;
  const paidMillis = Date.parse(purchase.purchaseCompletionTime ?? "");
  if (purchase.purchaseStateContext?.purchaseState !== "PURCHASED" || purchase.productLineItem?.length !== 1 ||
      line?.productId !== expected.sku || details?.purchaseOptionId !== expected.optionId ||
      !!details?.offerId || (details?.quantity ?? 1) !== 1 || details?.refundableQuantity === 0 ||
      purchase.regionCode !== "IN" || purchase.obfuscatedExternalAccountId !== expected.accountHash ||
      purchase.obfuscatedExternalProfileId !== expected.orderHash || !Number.isSafeInteger(paidMillis) ||
      paidMillis <= 0 || paidMillis > expected.now + 300_000) return { status: "invalid" };
  return { status: "valid", paidMillis,
    consumed: details?.consumptionState === "CONSUMPTION_STATE_CONSUMED" };
}
